package learn

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// gradeSkills is agent_learn.record_skill_turn_outcome (py 239-304): grade the
// auto-generated skills used this turn by how the turn went, into
// <home>/skill_stats.json (SkillRefiner.record_execution, refiner.py 214-250).
func gradeSkills(home string, t Turn, steps []nstep, now time.Time) (map[string]bool, error) {
	var names []string
	for _, n := range t.Skills {
		if n = strings.TrimSpace(n); n != "" {
			names = appendOnce(names, n)
		}
	}
	if len(names) == 0 {
		return nil, nil
	}
	real, successes := countRealSteps(steps)
	ratio := 0.0
	if len(steps) > 0 {
		ratio = float64(successes) / float64(len(steps))
	}
	var ok bool
	switch {
	case t.Aborted:
		ok = false
	case successes >= 3 && ratio >= 0.5:
		ok = true
	case real >= 3 && ratio < 0.5:
		ok = false
	default:
		return nil, nil // short turns are not evidence
	}
	var todo []string
	for _, n := range names {
		if isAutoGenerated(home, n) {
			todo = append(todo, n)
		}
	}
	if len(todo) == 0 {
		return nil, nil
	}
	path := filepath.Join(home, "skill_stats.json")
	top := map[string]any{"version": json.Number("1")}
	skills := map[string]any{}
	if raw, err := os.ReadFile(path); err == nil {
		dec := json.NewDecoder(bytes.NewReader(raw))
		dec.UseNumber()
		var data map[string]any
		if dec.Decode(&data) == nil && data != nil {
			if s, ok := data["skills"].(map[string]any); ok {
				top, skills = data, s
			}
		}
	}
	stamp := isoNow(now)
	out := map[string]bool{}
	for _, n := range todo {
		row, _ := skills[n].(map[string]any)
		if row == nil {
			row = map[string]any{}
		}
		recordExecution(row, ok, t.SessionID, aborted(t, ok), stamp)
		skills[n] = row
		out[n] = ok
	}
	top["skills"] = skills
	text, err := json.MarshalIndent(top, "", "  ")
	if err != nil {
		return out, err
	}
	if err := os.MkdirAll(home, 0o700); err != nil {
		return out, err
	}
	tmp := path + "." + newUUID()[:8] + ".tmp"
	if err := os.WriteFile(tmp, text, 0o600); err != nil {
		return out, err
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return out, err
	}
	return out, nil
}

func aborted(t Turn, ok bool) string {
	if t.Aborted && !ok {
		return "turn aborted"
	}
	return ""
}

func num(v any) int64 {
	switch t := v.(type) {
	case json.Number:
		if i, err := t.Int64(); err == nil {
			return i
		}
		f, _ := t.Float64()
		return int64(f)
	case float64:
		return int64(t)
	case int64:
		return t
	}
	return 0
}

func fnum(v any) float64 {
	switch t := v.(type) {
	case json.Number:
		f, _ := t.Float64()
		return f
	case float64:
		return t
	}
	return 0
}

func sub(row map[string]any, k string) map[string]any {
	m, _ := row[k].(map[string]any)
	if m == nil {
		m = map[string]any{}
	}
	row[k] = m
	return m
}

// recordExecution updates one stats row as SkillRefiner.record_execution does
// (duration 0, as agent_learn passes 0.0).
func recordExecution(row map[string]any, ok bool, session, errText, stamp string) {
	total := num(row["total_executions"]) + 1
	row["total_executions"] = total
	streak := num(row["consecutive_failures"])
	if ok {
		row["successes"] = num(row["successes"]) + 1
		streak = 0
		row["last_success_at"] = stamp
	} else {
		row["failures"] = num(row["failures"]) + 1
		streak++
		row["last_failure_at"] = stamp
	}
	for _, k := range []string{"successes", "failures"} {
		if _, has := row[k]; !has {
			row[k] = int64(0)
		}
	}
	row["consecutive_failures"] = streak
	avg := fnum(row["avg_duration_ms"])
	if total == 1 {
		avg = 0
	} else {
		avg = (avg*float64(total-1) + 0) / float64(total)
	}
	row["avg_duration_ms"] = avg
	row["last_executed"] = stamp
	if session != "" {
		by := sub(row, "execution_by_session")
		by[session] = num(by[session]) + 1
	} else {
		sub(row, "execution_by_session")
	}
	ce := sub(row, "common_errors")
	if errText != "" && !ok {
		k := rcut(errText, 80)
		ce[k] = num(ce[k]) + 1
	}
	if _, has := row["activations"]; !has {
		row["activations"] = int64(0)
	}
	sub(row, "activation_sessions")
	for _, k := range []string{"last_activated", "last_success_at", "last_failure_at"} {
		if _, has := row[k]; !has {
			row[k] = nil
		}
	}
}

// isAutoGenerated is agent_learn._is_auto_generated against the skills on disk.
func isAutoGenerated(home, name string) bool {
	if !isSafeSkillName(name) {
		return false
	}
	s, err := readSkill(filepath.Join(home, "skills", name))
	if err != nil {
		return false
	}
	v, _ := s.meta.get("auto_generated")
	switch t := v.(type) {
	case nil:
		return false
	case bool:
		return t
	case string:
		return t != ""
	case int:
		return t != 0
	case float64:
		return t != 0
	}
	return true
}
